// A record id: random text generated by HQ, never reused (docs/data-model.md).
// The domain only checks the shape. Generating one needs randomness, which
// lives in infrastructure.
import { err, ok, type Result } from "./result.ts";

declare const idBrand: unique symbol;
export type Id = string & { readonly [idBrand]: true };

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export function parseId(text: string): Result<Id, "invalid-id"> {
  return UUID.test(text) ? ok(text as Id) : err("invalid-id");
}
